def _parse_v3(text, *, full):
    """Parse a version 3 log.

    ``full`` replays every record from the base and populates compaction
    bookkeeping (used under the write lock).  Otherwise replay starts at the
    newest anchor in the (already bounded) text, which is what lock-free
    readers use.  Only the final line may be torn.
    """
    lines = _split_lines(text)
    if not lines:
        raise ValueError("state file is not valid JSON: the file is empty")
    last = len(lines) - 1

    def load_line(i):
        try:
            return json.loads(lines[i])
        except json.JSONDecodeError as exc:
            raise ValueError(f"state file is not valid JSON: {exc}") from exc

    # The first record is always a base; establish it.
    base_doc = load_line(0)
    if not isinstance(base_doc, dict):
        raise ValueError("state file must contain a JSON object")
    base_info = _v3_anchor_info(base_doc, allow_base=True)
    if base_info["kind"] != "base":
        raise ValueError("state file has an invalid base snapshot")

    # Walk the remaining records once.  Every record is checksum-verified and
    # the prev/seq chain is checked from the record right before it, so a
    # tampered record is caught even when an anchor follows it.
    state = _state_from_anchor(base_info)
    index = {key for key, _ in state["entries"]}
    max_first = state["entries"][-1][1] if state["entries"] else 0
    anchor_line_len = len(lines[0].encode("utf-8")) + 1
    good_offset = anchor_line_len
    delta_bytes = 0
    delta_count = 0
    latest_anchor = base_info
    latest_anchor_offset = anchor_line_len
    prev_tip = base_info["tip"]
    prev_seq = base_info["seq"]

    for i in range(1, len(lines)):
        line_len = len(lines[i].encode("utf-8")) + 1
        torn = i == last
        try:
            document = load_line(i)
            if not isinstance(document, dict):
                raise ValueError("state file must contain a JSON object")
            kind = document.get("kind")
            if kind == "anchor":
                info = _v3_anchor_info(document, allow_base=False)
                if info["prev"] != prev_tip or info["seq"] != prev_seq + 1:
                    raise ValueError("state file anchor chain is broken")
                if info["span"] != state["span"] or info["capacity"] != state["capacity"]:
                    raise ValueError("state file anchor changes the settings")
                # Counts are monotone across commits; the anchor's own
                # checksum already binds its snapshot to its bytes.
                if info["admitted"] < state["admitted"] or info["expired"] < state["expired"]:
                    raise ValueError("state file anchor counts are inconsistent")
            elif kind == "delta":
                max_first = _apply_v3_delta(lines[i], state, index, max_first)
            else:
                raise ValueError("state file holds a malformed record")
        except ValueError:
            if torn:
                break  # torn tail of an interrupted append: ignore it
            raise
        if kind == "anchor":
            state = _state_from_anchor(info)
            index = {key for key, _ in state["entries"]}
            max_first = state["entries"][-1][1] if state["entries"] else 0
            latest_anchor = info
            latest_anchor_offset = good_offset + line_len
            anchor_line_len = line_len
            delta_bytes = 0
            delta_count = 0
        else:
            delta_bytes += line_len
            delta_count += 1
        prev_tip = state["tip"]
        prev_seq = state["seq"]
        good_offset += line_len

    if not full:
        # Bounded reads may start at an anchor instead of the base; the
        # caller guarantees the text's first complete line is that anchor.
        # The walk above began at the base, which a bounded text does not
        # have, so this branch is reached only via _parse_v3_tail.
        raise AssertionError("bounded v3 reads use _parse_v3_tail")

    return _ParsedState(
        version=3,
        span=state["span"],
        capacity=state["capacity"],
        now=state["now"],
        admitted=state["admitted"],
        expired=state["expired"],
        entries=state["entries"],
        seq=state["seq"],
        tip=state["tip"],
        anchor_bytes=anchor_line_len,
        delta_bytes=delta_bytes,
        delta_count=delta_count,
        good_offset=good_offset,
    )


def _parse_v3_tail(text):
    """Parse a bounded tail whose first line should be the newest anchor.

    Used by lock-free readers.  Returns the tip parsed state.  Raises
    ValueError when the tail cannot establish a complete anchor-to-tip chain
    (the caller then re-reads the whole file).
    """
    lines = _split_lines(text)
    if not lines:
        raise ValueError("state file is not valid JSON: the file is empty")
    last = len(lines) - 1
    try:
        first_doc = json.loads(lines[0])
    except json.JSONDecodeError as exc:
        raise ValueError(f"state file is not valid JSON: {exc}") from exc
    if not isinstance(first_doc, dict):
        raise ValueError("state file must contain a JSON object")
    if first_doc.get("kind") not in ("base", "anchor"):
        raise ValueError("state file tail does not start at an anchor")
    info = _v3_anchor_info(first_doc, allow_base=True)
    state = _state_from_anchor(info)
    index = {key for key, _ in state["entries"]}
    max_first = state["entries"][-1][1] if state["entries"] else 0
    for i in range(1, len(lines)):
        try:
            max_first = _apply_v3_delta(lines[i], state, index, max_first)
        except ValueError:
            if i == last:
                break  # torn tail of an append in progress
            raise
    return _ParsedState(
        version=3,
        span=state["span"],
        capacity=state["capacity"],
        now=state["now"],
        admitted=state["admitted"],
        expired=state["expired"],
        entries=state["entries"],
        seq=state["seq"],
        tip=state["tip"],
        anchor_bytes=0,
        delta_bytes=0,
        delta_count=0,
        good_offset=-1,
    )


# ---------------------------------------------------------------------------
# File dispatch and lock-free reads
# ---------------------------------------------------------------------------


def _decode(raw):
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ValueError(f"state file is not valid UTF-8: {exc}") from exc


def _parse_log_text(text):
    """Parse a multi-line log, dispatching on the version of its first line."""
    first_line = text.split("\n", 1)[0]
    try:
        first = json.loads(first_line)
    except json.JSONDecodeError as exc:
        raise ValueError(f"state file is not valid JSON: {exc}") from exc
    if not isinstance(first, dict):
        raise ValueError("state file must contain a JSON object")
    version = _version_of(first)
    if version == 2:
        return _parse_v2(text)
    if version == 3:
        return _parse_v3(text, full=True)
    raise ValueError("state file has an unsupported version")


def _parse_state_file(path, *, full=True):
    """Read, verify and replay the state file at ``path``.

    Raises FileNotFoundError when the file is absent and ValueError for
    every form of corruption: bad formatting, a missing or unknown version,
    a missing or mismatched checksum, a broken chain or state that violates
    the window invariants.  A torn final record left by a crashed writer is
    not corruption; it is ignored and its offset reported.

    Pass ``full=False`` for a lock-free read: a bounded tail holding the
    newest anchor is enough to reconstruct the tip, and any problem falls
    back to a full read before it can surface.
    """
    if not full:
        return _parse_state_file_tail(path)
    try:
        with open(path, "rb") as fh:
            raw = fh.read()
    except FileNotFoundError:
        raise
    except OSError as exc:
        raise ValueError(f"state file cannot be read: {exc}") from exc
    text = _decode(raw)
    try:
        document = json.loads(text)
    except json.JSONDecodeError:
        document = None
    if document is not None:
        # A single JSON object: a version 1/2 document, or a v3 file that so
        # far holds only its base snapshot.
        if not isinstance(document, dict):
            raise ValueError("state file must contain a JSON object")
        version = _version_of(document)
        if version == 1:
            return _parse_v1(document, len(raw))
        if version == 2:
            return _parse_v2_single(document, len(raw))
        if version == 3:
            info = _v3_anchor_info(document, allow_base=True)
            if info["kind"] != "base":
                raise ValueError("state file has an invalid base snapshot")
            return _ParsedState(
                version=3,
                span=info["span"],
                capacity=info["capacity"],
                now=info["now"],
                admitted=info["admitted"],
                expired=info["expired"],
                entries=info["entries"],
                seq=info["seq"],
                tip=info["tip"],
                anchor_bytes=len(raw),
                delta_bytes=0,
                delta_count=0,
                good_offset=len(raw),
            )
        raise ValueError("state file has an unsupported version")
    return _parse_log_text(text)


def _parse_state_file_tail(path):
    """Lock-free read of the latest committed state without the flock."""
    try:
        with open(path, "rb") as fh:
            raw = fh.read()
    except FileNotFoundError:
        raise
    except OSError as exc:
        raise ValueError(f"state file cannot be read: {exc}") from exc
    text = _decode(raw)
    try:
        document = json.loads(text)
    except json.JSONDecodeError:
        document = None
    if document is not None:
        # Whole state in one JSON object (legacy, or a tiny current file).
        if not isinstance(document, dict):
            raise ValueError("state file must contain a JSON object")
        version = _version_of(document)
        if version == 1:
            return _parse_v1(document, len(raw))
        if version == 2:
            return _parse_v2_single(document, len(raw))
        if version == 3:
            return _parse_state_file(path, full=True)
        raise ValueError("state file has an unsupported version")
    # Multi-line log.  Try the bounded-tail fast path on raw trailing bytes,
    # then fall back to a full parse of this same read.
    first_nl = raw.find(b"\n")
    single_line = first_nl == -1
    if not single_line:
        lines = _split_lines(text)
        # Find the newest anchor inside this read and replay from there.
        anchor_i = None
        for i in range(len(lines) - 1, -1, -1):
            try:
                doc = json.loads(lines[i])
            except json.JSONDecodeError:
                continue
            if isinstance(doc, dict) and doc.get("kind") in ("base", "anchor"):
                anchor_i = i
                break
        if anchor_i is not None:
            tail_text = "\n".join(lines[anchor_i:]) + "\n"
            try:
                return _parse_v3_tail(tail_text)
            except ValueError:
                pass
    return _parse_log_text(text)


def read_settings(path):
    """Return ``(span, capacity)`` from a state file without opening a Window.

    Used by the command line to learn the construction settings before the
    window can be built.  Raises ValueError for a missing or corrupt file.
    """
    parsed = _parse_state_file(path)
    return parsed.span, parsed.capacity

